#include <set>
#include <iostream>
#include <algorithm>

int main() {
    std::multiset<int> ms = {1, 3, 3, 5, 6};

    // Finding bounds for 3
    auto range_3 = ms.equal_range(3);

    std::cout << "Range for 3: " 
              << *range_3.first << " to " 
              << *range_3.second << "\n";

    // Finding bounds for 4 (not present)
    auto range_4 = ms.equal_range(4);

    if (range_4.first == range_4.second) {
        std::cout << "4 not found. Next element: " 
                  << *range_4.first << "\n"; // Output: 5
    }
}
